37	export async function generate(input: {
38	  occasion: UiOccasion;
39	  formality: number | null;
40	  /** Refine "Lean into" colour families (`COLOR_FAMILIES` keys). A preference, not a filter. */
41	  lean: string[];
42	  /** Explicit user action only — the one way to spend an AI call on a day already answered. */
43	  regenerate?: boolean;
44	  city?: { lat: number; lon: number; label: string; source: LocationSource };
45	}): Promise<GenerateResult> {
46	  try {
47	    const supabase = await createClient();
48	    const {
49	      data: { user },
50	    } = await supabase.auth.getUser();
51	    if (!user) return { status: "error", message: "Not signed in" };
52	
53	    const { data: profile } = await supabase
54	      .from("profiles")
55	      .select(
56	        "archetype, formality_min, formality_max, location_lat, location_lon, location_label, location_source",
57	      )
58	      .eq("id", user.id)
59	      .single();
60	    const { data: itemsRaw } = await supabase
61	      .from("items")
62	      .select("*")
63	      .eq("user_id", user.id)
64	      .eq("archived", false);
65	    const items = itemsRaw ?? [];
66	    const byId = new Map(items.map((i) => [i.id, i]));
67	
68	    const loc = resolveLocation({ input: input.city, profile });
69	
70	    const now = new Date();
71	    const f = await fetchForecast(loc.lat, loc.lon);
72	    const advice = laterAdvice(f.hourly);
73	    const weather: WeatherPayload = {
74	      tempC: f.tempC,
75	      feelsLikeC: f.feelsLikeC,
76	      condition: f.condition,
77	      cityLabel: loc.label,
78	      timezone: f.timezone,
79	      locationOrigin: loc.origin,
80	      laterSentence: advice.sentence,
81	      adviceClause: advice.adviceClause,
82	      laterLabel: "Later",
83	      hourly: f.hourly,
84	    };
85	
86	    const today = localDateFor(now, f.timezone);
87	
88	    // The daily drop (Decision 5): today's looks are generated once and then
89	    // read back. Only an explicit regenerate spends an AI call on a day the
90	    // stylist has already answered.
91	    if (!input.regenerate) {
92	      const stored = await loadDailyLooks(user.id, input.occasion, today);
93	      if (stored?.length) {
94	        const paths = Array.from(
95	          new Set(
96	            stored
97	              .flatMap((s) => s.pieces.map((p) => byId.get(p.itemId)))
98	              .filter((it): it is NonNullable<typeof it> => Boolean(it))
99	              .map((it) => displayPath(it)),
100	          ),
101	        );
102	        const signed = await signItemImages(paths);
103	        const looks = reassembleLooks(stored, byId, signed, (id) => {
104	          const it = byId.get(id);
105	          return it ? displayPath(it) : undefined;
106	        });
107	        // null = the closet changed under the stored set; fall through and
108	        // regenerate rather than showing an outfit with a hole in it.
109	        if (looks) return { status: "ok", weather, looks };
110	      }
111	    }
112	
113	    await assertCanGenerate(user.id);
114	
115	    const candItems: CandidateItem[] = items.map((i) => ({
116	      id: i.id,
117	      category: i.category,
118	      colors: i.colors ?? [],
119	      formality: i.formality,
120	      seasons: i.seasons ?? [],
121	      material: i.material,
122	    }));
123	    // Occasion gives the context; the user's onboarding dress codes narrow it;
124	    // an explicit Refine formality overrides both.
125	    const band = applyFormalityOverride(
126	      personalBand(input.occasion, profile),
127	      input.formality,
128	    );
129	    const candidateArgs = {
130	      band,
131	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
132	      season: currentSeason(now),
133	      excludeItemIds: [],
134	      maxAccessories: 1,
135	    };
136	    const combos = buildCandidates(candItems, candidateArgs);
137	    if (combos.length === 0) {
138	      return { status: "empty", weather, missing: missingCategory(candItems, candidateArgs) };
139	    }
140	
141	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
142	    // The Refine colour pick lands here, in ranking — not in candidate building.
143	    // It reorders the shortlist toward the requested families and is dropped
144	    // silently when the closet cannot honour it.
145	    const top = rankTopN(combos, { aesthetic, band, lean: input.lean }, 20);
146	
147	    const { picks } = await rerank({
148	      combos: top.map((t) =>
149	        t.items.map((ci) => {
150	          const it = byId.get(ci.id)!;
151	          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
152	        }),
153	      ),
154	      aesthetic,
155	      occasion: input.occasion,
156	      weatherLabel: f.condition,
157	      tempC: f.tempC,
158	    });
159	
160	    const paths = Array.from(
161	      new Set(top.flatMap((t) => t.items.map((ci) => displayPath(byId.get(ci.id)!)))),
162	    );
163	    const signed = await signItemImages(paths);
164	
165	    const looks: Look[] = picks.map((p) => {
166	      const combo = top[p.combo_index]?.items ?? top[0].items;
167	      const dbItems = combo.map((ci) => byId.get(ci.id)!);
168	      const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
169	      const pieces: LookPiece[] = dbItems.map((d, idx) => ({
170	        itemId: d.id,
171	        category: d.category,
172	        subcategory: d.subcategory ?? null,
173	        brand: d.brand ?? null,
174	        name: d.name ?? null,
175	        colors: d.colors ?? [],
176	        cutoutUrl: signed.get(displayPath(d)) ?? "",
177	        slot: slots[idx],
178	      }));
179	      return { name: p.name, why: p.why, pieces, anchorIndex: staggerOrder(slots)[0] };
180	    });
181	
182	    // Fire-and-forget would be simpler, but a failed write means the user pays
183	    // for another AI call on their next tap — worth awaiting.
184	    await saveDailyLooks(user.id, input.occasion, today, weather, looks);
185	
186	    return { status: "ok", weather, looks };
187	  } catch (e) {
188	    console.error("[generate] failed:", e);
189	    return { status: "error", message: e instanceof Error ? e.message : "Generation failed" };
190	  }
191	}
