193	/**
194	 * The single write path for a user's location. `generate` stays read-only.
195	 * Called by the client after a successful generate for a location the user
196	 * actually supplied (geolocation or city search) — never for the profile or
197	 * default fallback, where there is nothing new to write.
198	 */
199	export async function saveLocation(input: unknown): Promise<void> {
200	  const d = LocationInputSchema.parse(input);
201	
202	  const supabase = await createClient();
203	  const {
204	    data: { user },
205	  } = await supabase.auth.getUser();
206	  if (!user) return;
207	
208	  await supabase
209	    .from("profiles")
210	    .update({
211	      location_lat: roundCoord(d.lat),
212	      location_lon: roundCoord(d.lon),
213	      location_label: d.label,
214	      location_source: d.source,
215	      location_timezone: d.timezone,
216	      location_updated_at: new Date().toISOString(),
217	    })
218	    .eq("id", user.id);
219	}
