221	/**
222	 * The seed for the morning. Cheap on purpose — one profile read, date math, NO
223	 * AI and NO weather — so the client can pick the right occasion before the first
224	 * generate without adding latency.
225	 */
226	export async function predictDefaultOccasion(): Promise<{ occasion: UiOccasion; reason: string }> {
227	  const supabase = await createClient();
228	  const {
229	    data: { user },
230	  } = await supabase.auth.getUser();
231	  if (!user) return { occasion: "everyday", reason: defaultReason("everyday") };
232	
233	  const { data: profile } = await supabase
234	    .from("profiles")
235	    .select("occasions, location_timezone")
236	    .eq("id", user.id)
237	    .single();
238	
239	  const tz = profile?.location_timezone ?? "UTC";
240	  const occasion = predictOccasion(new Date(), tz, profile?.occasions ?? []);
241	  return { occasion, reason: defaultReason(occasion) };
242	}
