244	/**
245	 * Record that the user chose an occasion other than the predicted default.
246	 * Fire-and-forget: the caller does not await the outcome, and a failure here
247	 * must never affect the looks. Guards `chosen === predicted` so a no-op tap is
248	 * not logged as an override.
249	 */
250	export async function logOccasionOverride(input: {
251	  predicted: UiOccasion;
252	  chosen: UiOccasion;
253	}): Promise<void> {
254	  if (input.chosen === input.predicted) return;
255	
256	  const supabase = await createClient();
257	  const {
258	    data: { user },
259	  } = await supabase.auth.getUser();
260	  if (!user) return;
261	
262	  const { data: profile } = await supabase
263	    .from("profiles")
264	    .select("location_timezone")
265	    .eq("id", user.id)
266	    .single();
267	
268	  const today = localDateFor(new Date(), profile?.location_timezone ?? "UTC");
269	  await recordOverride(user.id, today, input.predicted, input.chosen);
270	}
